                double p0=root.assignments()[i][v0],p1=root.assignments()[i][v1];require(p0+p1>0,"Zero-mass source edge average; no fallback invented");double t=(root.times()[v0]*p0+root.times()[v1]*p1)/(p0+p1);m.close(t,f.number(i,"t"),"Original assignment-weighted root-time projection");require(Double.isFinite(f.number(i,"t")),"Original nonfinite projected time is outside this complete coordinate profile; no partial result admitted");allTimes[mapping][i]=f.number(i,"t");String segment=text(root.info().value(root.forks()[v0]?v1:v0,"seg"));m.identity(f.value(i,"seg"),segment,"Original fork-dependent segment assignment");int label=segmentLabel(segment,s);votes[i][label-1]++;
