        policy(spec,"missing_milestones",missing,"MISSING ORIGINAL MILESTONES: strict midpoint/single-cell segment states remain missing; no annotation is imputed",warnings);if(ambiguousReassignments>0)warnings.add(text(spec.get("id"))+": UPSTREAM TIED SEGMENT REASSIGNMENTS retained for "+ambiguousReassignments+" cells. Native auditing admits the bounded tied-choice family; NumPy performs the actual sort. No Java tie break or independent random/refit claim.");
